import { mkdir, writeFile } from "node:fs/promises";

import { payoutSample, batchedPayoutSample } from "../shared/rote/samples.js";
await mkdir("data/sample/payouts", { recursive: true });
for (let week = 1; week <= 20; week++) {
  const sample = payoutSample(week);
  for (const kind of ["payouts", "bank"] as const)
    await writeFile(
      `data/sample/payouts/week-${String(week).padStart(2, "0")}-${kind}.csv`,
      sample[kind],
    );
}
await writeFile(
  "data/sample/payouts/README.md",
  "# Sample payout data\n\nSynthetic seeded data generated by scripts/gen-payouts.ts; seed = 3100 + week. 20 paired weeks, 25 payouts per week, fees and refunds; dates and currency formatting differ between exports. No batching or realistic settlement delay is simulated yet. Not real Stripe/customer data.\n",
);
console.log("Generated 20 sample weeks (40 CSV files), 25 payouts per week.");

await mkdir("data/sample/payouts-batched", { recursive: true });
for (let week = 1; week <= 20; week++) {
  const sample = batchedPayoutSample(week);
  for (const kind of ["payouts", "bank"] as const)
    await writeFile(
      `data/sample/payouts-batched/week-${String(week).padStart(2, "0")}-${kind}.csv`,
      sample[kind],
    );
  await writeFile(
    `data/sample/payouts-batched/week-${String(week).padStart(2, "0")}-reference.json`,
    JSON.stringify(sample.expected, null, 2) + "\n",
  );
}
await writeFile(
  "data/sample/payouts-batched/README.md",
  "# Synthetic batched payouts\n\nGenerated by scripts/gen-payouts.ts; seed = 9100 + week. 20 weeks, 25 transactions/week, batches and refund settlements, rounded fees, integer-cent monetary fields, 1–3 calendar-day bank delays, reversed statement order and differing date/amount formats. Reference JSON is independent generator ledger truth, not pipeline output. USD-only synthetic fixture, not a claim to match real Stripe or bank export schemas.\n",
);
console.log(
  "Generated 20 enhanced batched weeks, paired CSVs and independent references.",
);
